    [('分阶段放量', '<p>小比例阶段攒不够错误,要到足够的比例才发现;放大越早发现越快,受影响的用户越多。</p>'),
     ('观察窗口', '<p>按 canary 自己收到的请求数来定窗口,而不是固定几分钟。</p>'),
     ('蓝绿切换', '<p>reload 后新旧 worker 并存,旧版本要等在途请求处理完再下线。</p>')],
